DROP TABLE IF EXISTS `policy_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `policy_details` (
  `Policy_ID` varchar(50) NOT NULL,
  `Policy_Type` varchar(100) NOT NULL,
  `Coverage_Amount` int DEFAULT NULL,
  `Premium_Amount` decimal(15,2) DEFAULT NULL,
  `Policy_Start_Date` date DEFAULT NULL,
  `Policy_End_Date` date DEFAULT NULL,
  `Payment_Frequency` varchar(50) DEFAULT NULL,
  `Status` varchar(50) DEFAULT NULL,
  `Customer_ID` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`Policy_ID`),
  KEY `Customer_ID` (`Customer_ID`),
  CONSTRAINT `policy_details_ibfk_1` FOREIGN KEY (`Customer_ID`) REFERENCES `customer_information` (`Customer_ID`),
  CONSTRAINT `policy_details_chk_1` CHECK ((`Coverage_Amount` >= 0)),
  CONSTRAINT `policy_details_chk_2` CHECK ((`Premium_Amount` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

